		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 3, "</div><!-- Auto-reload on server restart during development --><script>\n\t\t\t// Use SSE to detect server restarts instead of polling\n\t\t\t// Listen for SSE connection errors which indicate server is down\n\t\t\tdocument.body.addEventListener('htmx:sseError', function(e) {\n\t\t\t\tconsole.log('SSE connection error - server may be restarting');\n\t\t\t});\n\t\t\t\n\t\t\tdocument.body.addEventListener('htmx:sseClose', function(e) {\n\t\t\t\tconsole.log('SSE connection closed - server may be restarting');\n\t\t\t});\n\t\t\t\n\t\t\t// When SSE reconnects successfully after being down, reload the page\n\t\t\tlet wasDisconnected = false;\n\t\t\tdocument.body.addEventListener('htmx:sseOpen', function(e) {\n\t\t\t\tif (wasDisconnected) {\n\t\t\t\t\tconsole.log('SSE reconnected after disconnect - server restarted, reloading...');\n\t\t\t\t\twindow.location.reload();\n\t\t\t\t}\n\t\t\t});\n\t\t\t\n\t\t\tdocument.body.addEventListener('htmx:sseBeforeMessage', function(e) {\n\t\t\t\twasDisconnected = false;\n\t\t\t});\n\t\t</script><!-- HTMX: Initialize components on dynamic content load --><script>\n\t\t\t// HTMX automatically processes elements with hx-* attributes\n\t\t\t// Only need to initialize custom components that aren't HTMX-enhanced\n\t\t\tdocument.body.addEventListener('htmx:load', function(evt) {\n\t\t\t\tconsole.log('HTMX loaded new content - initializing components');\n\t\t\t\t\n\t\t\t\t// Attach memory estimation event listeners to all forms\n\t\t\t\t// (This is custom functionality, not HTMX-related)\n\t\t\t\tinitMemoryEstimation();\n\t\t\t});\n\t\t\t\n\t\t\t// SSE Event Logging for Development/Debugging\n\t\t\tif (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {\n\t\t\t\tconst sseEvents = ['htmx:sseOpen', 'htmx:sseError', 'htmx:sseClose', 'htmx:sseMessage', 'htmx:sseBeforeMessage'];\n\t\t\t\tsseEvents.forEach(function(eventName) {\n\t\t\t\t\tdocument.body.addEventListener(eventName, function(e) {\n\t\t\t\t\t\tconst shortName = eventName.replace('htmx:', '');\n\t\t\t\t\t\tif (shortName === 'sseMessage') {\n\t\t\t\t\t\t\t// Log SSE messages with event type\n\t\t\t\t\t\t\tconsole.log('[SSE] Message received:', {\n\t\t\t\t\t\t\t\tevent: e.detail.event || 'message',\n\t\t\t\t\t\t\t\ttimestamp: new Date().toLocaleTimeString()\n\t\t\t\t\t\t\t});\n\t\t\t\t\t\t} else if (shortName === 'sseError') {\n\t\t\t\t\t\t\tconsole.error('[SSE] Error:', e.detail.error ? e.detail.error.message : 'unknown');\n\t\t\t\t\t\t} else if (shortName === 'sseOpen') {\n\t\t\t\t\t\t\tconsole.log('[SSE] Connection opened');\n\t\t\t\t\t\t} else if (shortName === 'sseClose') {\n\t\t\t\t\t\t\tconsole.log('[SSE] Connection closed');\n\t\t\t\t\t\t}\n\t\t\t\t\t});\n\t\t\t\t});\n\t\t\t\tconsole.log('[SSE] Debug logging enabled for localhost');\n\t\t\t}\n\t\t\t\n\t\t\t// Memory estimation for model loading\n\t\t\tfunction formatBytes(bytes) {\n\t\t\t\tif (bytes === 0) return '0 B';\n\t\t\t\tconst k = 1024;\n\t\t\t\tconst sizes = ['B', 'KB', 'MB', 'GB', 'TB'];\n\t\t\t\tconst i = Math.floor(Math.log(bytes) / Math.log(k));\n\t\t\t\treturn Math.round(bytes / Math.pow(k, i) * 10) / 10 + ' ' + sizes[i];\n\t\t\t}\n\t\t\t\n\t\t\tfunction estimateMemoryUsage(modelSizeBytes, contextSize, ngl, totalLayers) {\n\t\t\t\t// Model weights (proportional to GPU layers)\n\t\t\t\tconst layerFraction = totalLayers > 0 ? (ngl / totalLayers) : 1.0;\n\t\t\t\tconst modelWeightsGPU = modelSizeBytes * layerFraction;\n\t\t\t\t\n\t\t\t\t// KV cache: ~0.25 MB per token for large models (empirical)\n\t\t\t\tconst kvCacheBytes = contextSize * 0.25 * 1024 * 1024;\n\t\t\t\t\n\t\t\t\t// Total GPU memory estimate\n\t\t\t\tconst totalGPUBytes = modelWeightsGPU + kvCacheBytes;\n\t\t\t\t\n\t\t\t\treturn {\n\t\t\t\t\ttotal: totalGPUBytes,\n\t\t\t\t\tmodelWeights: modelWeightsGPU,\n\t\t\t\t\tkvCache: kvCacheBytes\n\t\t\t\t};\n\t\t\t}\n\t\t\t\n\t\t\tfunction updateMemoryEstimate(form) {\n\t\t\t\tconst modelSizeBytes = parseInt(form.dataset.modelSize) || 0;\n\t\t\t\tconst parametersCount = parseInt(form.dataset.parameters) || 0;\n\t\t\t\t\n\t\t\t\t// Estimate layers from parameters (rough heuristic: ~1B params per layer for large models)\n\t\t\t\t// For 78B model, typical layer count is 80-86\n\t\t\t\tconst estimatedLayers = parametersCount > 0 ? Math.max(80, Math.round(parametersCount / 1e9)) : 80;\n\t\t\t\t\n\t\t\t\tconst contextSelect = form.querySelector('select[name=\"context_size\"]');\n\t\t\t\tconst nglSelect = form.querySelector('select[name=\"ngl\"]');\n\t\t\t\tconst estimateDiv = form.querySelector('.memory-estimate');\n\t\t\t\t\n\t\t\t\tif (!contextSelect || !nglSelect || !estimateDiv || modelSizeBytes === 0) {\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\t\n\t\t\t\tconst contextValue = contextSelect.value || '131072';\n\t\t\t\tconst nglValue = nglSelect.value || '999';\n\t\t\t\t\n\t\t\t\tconst contextSize = parseInt(contextValue);\n\t\t\t\tconst ngl = nglValue === '999' ? estimatedLayers : parseInt(nglValue);\n\t\t\t\t\n\t\t\t\tconst estimate = estimateMemoryUsage(modelSizeBytes, contextSize, ngl, estimatedLayers);\n\t\t\t\tconst totalGB = estimate.total / (1024 * 1024 * 1024);\n\t\t\t\t\n\t\t\t\t// Determine warning level\n\t\t\t\tlet warningClass = '';\n\t\t\t\tlet warningIcon = '';\n\t\t\t\tlet warningText = '';\n\t\t\t\t\n\t\t\t\tif (totalGB > 128) {\n\t\t\t\t\twarningClass = 'error';\n\t\t\t\t\twarningIcon = '🔴';\n\t\t\t\t\twarningText = 'EXCEEDS SYSTEM LIMIT (128GB)';\n\t\t\t\t} else if (totalGB > 64) {\n\t\t\t\t\twarningClass = 'warning';\n\t\t\t\t\twarningIcon = '⚠️';\n\t\t\t\t\twarningText = 'May trigger ROCm >64GB bug';\n\t\t\t\t} else if (totalGB > 48) {\n\t\t\t\t\twarningClass = 'info';\n\t\t\t\t\twarningIcon = 'ℹ️';\n\t\t\t\t\twarningText = 'High memory usage';\n\t\t\t\t} else {\n\t\t\t\t\twarningClass = 'success';\n\t\t\t\t\twarningIcon = '✓';\n\t\t\t\t\twarningText = 'Safe range';\n\t\t\t\t}\n\t\t\t\t\n\t\t\t\testimateDiv.innerHTML = `\n\t\t\t\t\t<div style=\"display: flex; align-items: center; gap: 8px; padding: 8px; background: rgba(30, 41, 59, 0.6); border-radius: 4px; border-left: 3px solid ${warningClass === 'error' ? '#ef4444' : warningClass === 'warning' ? '#f59e0b' : warningClass === 'info' ? '#3b82f6' : '#10b981'};\">\n\t\t\t\t\t\t<span style=\"font-size: 16px;\">${warningIcon}</span>\n\t\t\t\t\t\t<div style=\"flex: 1;\">\n\t\t\t\t\t\t\t<div style=\"font-size: 13px; font-weight: 600; color: #e2e8f0;\">\n\t\t\t\t\t\t\t\tEst. GPU Memory: ${formatBytes(estimate.total)} (~${totalGB.toFixed(1)} GB)\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div style=\"font-size: 11px; color: #94a3b8;\">\n\t\t\t\t\t\t\t\t${warningText} • Layers: ${ngl}/${estimatedLayers} • Context: ${(contextSize/1024).toFixed(0)}K\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t`;\n\t\t\t}\n\t\t\t\n\t\t\tfunction initMemoryEstimation() {\n\t\t\t\tconst forms = document.querySelectorAll('form[hx-post=\"/api/servers/start\"]');\n\t\t\t\tforms.forEach(form => {\n\t\t\t\t\tconst contextSelect = form.querySelector('select[name=\"context_size\"]');\n\t\t\t\t\tconst nglSelect = form.querySelector('select[name=\"ngl\"]');\n\t\t\t\t\t\n\t\t\t\t\tif (contextSelect && nglSelect) {\n\t\t\t\t\t\tcontextSelect.addEventListener('change', () => updateMemoryEstimate(form));\n\t\t\t\t\t\tnglSelect.addEventListener('change', () => updateMemoryEstimate(form));\n\t\t\t\t\t\t\n\t\t\t\t\t\t// Initial update\n\t\t\t\t\t\tupdateMemoryEstimate(form);\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t}\n\t\t\t\n\t\t\t// Initialize on page load\n\t\t\tdocument.addEventListener('DOMContentLoaded', initMemoryEstimation);\n\t\t</script></body></html>")
